package ru.ryadom.calendar;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.net.Uri;import android.provider.CalendarContract;import org.json.*;import java.time.*;import java.util.*;
final class DeviceWrites {
 static final String OWNER="peklo-local",NAME="peklo-export",LABEL="Пекло · расписание";
 static boolean permitted(Context c){return c.checkSelfPermission(Manifest.permission.WRITE_CALENDAR)==PackageManager.PERMISSION_GRANTED&&c.checkSelfPermission(Manifest.permission.READ_CALENDAR)==PackageManager.PERMISSION_GRANTED;}
 static void require(Context c)throws Providers.Failure{if(!permitted(c))throw new Providers.Failure("Разрешите чтение и запись календаря в настройках Android.",false);}
 static long eventId(Event e){return Long.parseLong(e.id.split("\\|")[0]);}
 static Uri adapter(Uri uri){return uri.buildUpon().appendQueryParameter(CalendarContract.CALLER_IS_SYNCADAPTER,"true").appendQueryParameter("account_name",OWNER).appendQueryParameter("account_type",CalendarContract.ACCOUNT_TYPE_LOCAL).build();}
 static boolean exported(Context c,String calendar){try(Cursor row=c.getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"account_name","account_type","name"},"_id=?",new String[]{calendar},null)){return row!=null&&row.moveToFirst()&&OWNER.equals(row.getString(0))&&CalendarContract.ACCOUNT_TYPE_LOCAL.equals(row.getString(1))&&NAME.equals(row.getString(2));}}
 static boolean writable(Context c,String calendar){if(!permitted(c))return false;try(Cursor row=c.getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{"calendar_access_level"},"_id=?",new String[]{calendar},null)){return row!=null&&row.moveToFirst()&&row.getInt(0)>=CalendarContract.Calendars.CAL_ACCESS_CONTRIBUTOR&&!exported(c,calendar);}}
 static ContentValues values(Event e){ContentValues v=new ContentValues();v.put("title",e.title);v.put("description",e.description);v.put("eventLocation",e.location);v.put("dtstart",e.allDay?utcDay(e.start):e.start);v.put("dtend",e.allDay?utcDay(e.end):e.end);v.put("allDay",e.allDay?1:0);v.put("eventTimezone",e.allDay?"UTC":"Europe/Moscow");v.put("eventStatus",CalendarContract.Events.STATUS_CONFIRMED);v.put("availability",CalendarContract.Events.AVAILABILITY_BUSY);v.put("hasAlarm",e.reminderMinutes>=0?1:0);return v;}
 static long utcDay(long value){return Instant.ofEpochMilli(value).atZone(Event.ZONE).toLocalDate().atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();}
 static Event save(Context c,String calendar,Event before,Event desired,String token)throws Exception{
  require(c);if(!writable(c,calendar))throw new Providers.Failure("Этот календарь доступен только для чтения.",false);if(before!=null&&before.recurring)throw new Providers.Failure("Повторяющуюся встречу пока редактируйте в приложении её календаря.",false);
  ContentResolver r=c.getContentResolver();long id=before==null?0:eventId(before);String marker="peklo:"+token;
  if(id==0)try(Cursor rows=r.query(CalendarContract.Events.CONTENT_URI,new String[]{"_id"},"calendar_id=? AND customAppUri=? AND deleted=0",new String[]{calendar,marker},null)){if(rows==null)throw new Providers.Failure("Не удалось проверить сохранение встречи.",false);if(rows.moveToFirst())id=rows.getLong(0);}
  ContentValues v=values(desired);v.put("calendar_id",Long.parseLong(calendar));if(before==null){v.put("customAppPackage",c.getPackageName());v.put("customAppUri",marker);}
  ArrayList<ContentProviderOperation> ops=new ArrayList<>();if(id==0)ops.add(ContentProviderOperation.newInsert(CalendarContract.Events.CONTENT_URI).withValues(v).build());else{ops.add(ContentProviderOperation.newUpdate(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id)).withValues(v).withExpectedCount(1).build());ops.add(ContentProviderOperation.newDelete(CalendarContract.Reminders.CONTENT_URI).withSelection("event_id=?",new String[]{""+id}).build());}
  if(desired.reminderMinutes>=0){ContentProviderOperation.Builder reminder=ContentProviderOperation.newInsert(CalendarContract.Reminders.CONTENT_URI).withValue("minutes",desired.reminderMinutes).withValue("method",CalendarContract.Reminders.METHOD_ALERT);if(id==0)reminder.withValueBackReference("event_id",0);else reminder.withValue("event_id",id);ops.add(reminder.build());}
  ContentProviderResult[] result=r.applyBatch(CalendarContract.AUTHORITY,ops);if(id==0)id=ContentUris.parseId(result[0].uri);Event saved=Event.from(desired.json());saved.id=id+"|"+desired.start;saved.stableId=""+id;saved.calendar=calendar;return saved;
 }
 static void delete(Context c,Event e)throws Exception{require(c);if(e.recurring)throw new Providers.Failure("Повторяющуюся встречу удалите в приложении её календаря.",false);if(!writable(c,e.calendar))throw new Providers.Failure("Нет права записи в календарь.",false);Uri uri=ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,eventId(e));try(Cursor row=c.getContentResolver().query(uri,new String[]{"calendar_id"},null,null,null)){if(row==null)throw new Providers.Failure("Не удалось проверить встречу.",false);if(!row.moveToFirst())return;if(!e.calendar.equals(row.getString(0)))throw new Providers.Failure("Календарь встречи изменился.",false);}c.getContentResolver().delete(uri,null,null);}
 static long exportCalendar(Context c,boolean create)throws Exception{require(c);ContentResolver r=c.getContentResolver();try(Cursor rows=r.query(CalendarContract.Calendars.CONTENT_URI,new String[]{"_id"},"account_name=? AND account_type=? AND name=?",new String[]{OWNER,CalendarContract.ACCOUNT_TYPE_LOCAL,NAME},null)){if(rows==null)throw new Providers.Failure("Системный календарь недоступен.",false);if(rows.moveToFirst())return rows.getLong(0);}if(!create)return 0;
  ContentValues v=new ContentValues();v.put("account_name",OWNER);v.put("account_type",CalendarContract.ACCOUNT_TYPE_LOCAL);v.put("name",NAME);v.put("calendar_displayName",LABEL);v.put("calendar_color",0xff276a4f);v.put("calendar_access_level",CalendarContract.Calendars.CAL_ACCESS_READ);v.put("ownerAccount",OWNER);v.put("calendar_timezone","Europe/Moscow");v.put("visible",1);v.put("sync_events",1);v.put("allowedReminders","0");return ContentUris.parseId(r.insert(adapter(CalendarContract.Calendars.CONTENT_URI),v));
 }
 static void publish(Context c,JSONObject data)throws Exception{
  boolean enabled=data.optBoolean("systemExport");if(!enabled&&!permitted(c))return;long calendar=exportCalendar(c,enabled);if(calendar==0)return;ContentResolver r=c.getContentResolver();Map<String,Long> existing=new HashMap<>();try(Cursor rows=r.query(CalendarContract.Events.CONTENT_URI,new String[]{"_id","_sync_id"},"calendar_id=? AND deleted=0",new String[]{""+calendar},null)){if(rows==null)throw new Providers.Failure("Системные события недоступны.",false);while(rows.moveToNext())existing.put(rows.getString(1),rows.getLong(0));}
  Map<String,String> types=new HashMap<>();JSONArray accounts=Store.array(data,"accounts");for(int i=0;i<accounts.length();i++)types.put(accounts.getJSONObject(i).optString("id"),accounts.getJSONObject(i).optString("type"));
  if(enabled)for(Event e:Sync.visible(data,false)){if("device".equals(types.get(e.source))||!e.copyToken.isEmpty())continue;String key=Mirror.hash(e.source+"|"+(e.stableId.isEmpty()?e.id:e.stableId));Long id=existing.remove(key);Event copy=Event.from(e.json());copy.reminderMinutes=-1;ContentValues v=values(copy);v.put("calendar_id",calendar);v.put("_sync_id",key);v.put("dirty",0);v.put("sync_data1",Mirror.fingerprint(copy));if(id==null)r.insert(adapter(CalendarContract.Events.CONTENT_URI),v);else{ // Avoid observer loops: update only if the exported payload changed.
    String fingerprint=Mirror.fingerprint(copy);try(Cursor old=r.query(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id),new String[]{"sync_data1"},null,null,null)){if(old!=null&&old.moveToFirst()&&fingerprint.equals(old.getString(0)))continue;}v.put("sync_data1",fingerprint);r.update(adapter(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id)),v,null,null);}}
  for(long id:existing.values())r.delete(adapter(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id)),null,null);
 }
}
